// Handle Shopify API errors gracefully
const globalData = $getWorkflowStaticData('global');
const intervalMinutes = $('Schedule Trigger').params.rule.interval[0].minutesInterval || 30;
const currentTime = $now.toFormat('yyyy-MM-dd HH:mm:ss');

// Increment specific API error counter
globalData.apiErrorCount = globalData.apiErrorCount ? globalData.apiErrorCount + 1 : 1;

if (!globalData.firstFailingTime) {
    globalData.firstFailingTime = currentTime;
}

const totalDowntimeMinutes = globalData.apiErrorCount * intervalMinutes;
const errorMessage = $input.first().json.error?.message || 'Unknown API error';

const alertMessage = `⚠️ *SHOPIFY API ERROR* (Consecutive API Error #${globalData.apiErrorCount})\n\n⏰ Time: ${currentTime}\n🕒 Failing Since: ${globalData.firstFailingTime} (~${totalDowntimeMinutes} mins)\n❌ Error: ${errorMessage}\n\n⚡ Action Required:\n  • Check Shopify status page\n  • Verify API credentials\n  • Check n8n logs for details\n  • Your store may be unreachable`;

return {json: {
  alertMessage: alertMessage,
  apiErrorCount: globalData.apiErrorCount,
  firstFailingTime: globalData.firstFailingTime,
  totalDowntimeMinutes: totalDowntimeMinutes,
  isApiError: true,
  isTestMode: false,
  headerIcon: "⚠️",
  headerTitle: "SHOPIFY API ERROR",
  themeColor: "#dd6b20"
}};

const globalData = $getWorkflowStaticData('global');
const intervalMinutes = $('Schedule Trigger').params.rule.interval[0].minutesInterval || 30;
const currentTime = $now.toFormat('yyyy-MM-dd HH:mm:ss');

// Handle Stale Data Check
if (globalData.firstFailingTime) {
  const hoursSinceFirst = $now.diff(DateTime.fromISO(globalData.firstFailingTime), 'hours').hours;
  if (hoursSinceFirst > 24) {
    delete globalData.firstFailingTime;
    delete globalData.failedCount;
  }
}

globalData.failedCount = globalData.failedCount ? globalData.failedCount + 1 : 1;

if (!globalData.firstFailingTime) {
    globalData.firstFailingTime = currentTime;
}

const totalDowntimeMinutes = globalData.failedCount * intervalMinutes;

// Determine context mode
const headerIcon = "🚨";
const headerTitle = "NO ORDERS ALERT";

const alertMessage = `${headerIcon} *${headerTitle}* (Consecutive Alert #${globalData.failedCount})\n\n⏰ Time Checked: ${currentTime}\n🕒 Failing Since: ${globalData.firstFailingTime} (~${totalDowntimeMinutes} mins without new orders)\n📊 Status: No orders found in the last ${intervalMinutes} minutes.\n⚠️ Action Required: Please check your Shopify store for:\n  • Payment gateway issues\n  • Checkout errors\n  • Traffic anomalies\n  • API connectivity`;

return {json: {
  alertMessage: alertMessage,
  failedCount: globalData.failedCount,
  firstFailingTime: globalData.firstFailingTime,
  totalDowntimeMinutes: totalDowntimeMinutes,
  headerIcon: headerIcon,
  headerTitle: headerTitle,
  themeColor: "#e53e3e"
}};

const globalData = $getWorkflowStaticData('global');
const intervalMinutes = $('Schedule Trigger').params.rule.interval[0].minutesInterval || 30;

let wasFailing = globalData.failedCount > 0 || globalData.apiErrorCount > 0;
let downtimeMinutes = ((globalData.failedCount || 0) + (globalData.apiErrorCount || 0)) * intervalMinutes;
let failingSince = globalData.firstFailingTime || 'Unknown';

// Clear all tracking variables
delete globalData.failedCount;
delete globalData.apiErrorCount;
delete globalData.firstFailingTime;

// If we were previously failing, generate a recovery payload
if (wasFailing) {
  const headerIcon = "✅";
  const headerTitle = "SYSTEM RECOVERED";
  const alertMessage = `${headerIcon} *${headerTitle}*\n\n🎉 Orders are successfully flowing again!\n🕒 Outage Started: ${failingSince}\n⏱️ Approx Downtime: ${downtimeMinutes} mins`;

  return [{ json: {
    alertMessage: alertMessage,
    totalDowntimeMinutes: downtimeMinutes,
    firstFailingTime: failingSince,
    isRecovery: true,
    headerIcon: headerIcon,
    headerTitle: headerTitle,
    themeColor: "#38a169"
  }}];
}

// Always return an item so the downstream IF node can cleanly stop execution
return [{ json: { 
  isRecovery: false, 
  message: "No active outage to recover from. Counters cleared."
}}];
